import type { HTMLArkProps } from '@ark-ui/solid/factory';
import { ark } from '@ark-ui/solid/factory';
import { clsx } from 'clsx';
import type { JSX } from 'solid-js';
import { splitProps } from 'solid-js';
import { Dynamic } from 'solid-js/web';
import styles from './Text.module.css';

type TextElement = 'p' | 'span' | 'small' | 'strong' | 'em' | 'div';
type TextSize = 'xs' | 'sm' | 'md' | 'lg' | 'xl';
type TextWeight = 'regular' | 'medium' | 'semibold' | 'bold';
type TextTone = 'default' | 'muted' | 'primary' | 'destructive';
type TextAlign = 'start' | 'center' | 'end' | 'left' | 'right' | 'justify';

type TextRootProps = HTMLArkProps<'p'> & {
  as?: TextElement;
  size?: TextSize;
  weight?: TextWeight;
  tone?: TextTone;
  align?: TextAlign;
  truncate?: boolean;
  lineClamp?: number;
};

function Text(props: TextRootProps) {
  const [local, others] = splitProps(props, [
    'as',
    'size',
    'weight',
    'tone',
    'align',
    'truncate',
    'lineClamp',
    'class',
    'style',
  ]);
  const as = () => local.as ?? 'p';
  const clamp = () =>
    Number.isInteger(local.lineClamp) && (local.lineClamp ?? 0) > 0 ? local.lineClamp : undefined;
  const style = (): JSX.CSSProperties | string | undefined => {
    const value = clamp();

    if (value === undefined) return local.style;
    if (typeof local.style === 'string') return `${local.style};-webkit-line-clamp:${value}`;
    return { ...local.style, '-webkit-line-clamp': value };
  };

  return (
    <Dynamic
      component={ark[as()] as typeof ark.p}
      {...others}
      data-scope="text"
      data-part="root"
      data-slot="text-root"
      data-size={local.size ?? (as() === 'small' ? 'sm' : 'md')}
      data-weight={local.weight ?? (as() === 'strong' ? 'semibold' : 'regular')}
      data-tone={local.tone ?? 'default'}
      data-align={local.align}
      data-truncate={local.truncate ? '' : undefined}
      data-line-clamp={clamp() === undefined ? undefined : ''}
      class={clsx(styles.root, local.class)}
      style={style()}
    />
  );
}

export { Text };
export type { TextAlign, TextElement, TextRootProps, TextSize, TextTone, TextWeight };

@layer moduix.components {
  .root {
    margin: 0;
    color: var(--moduix-color-foreground);
    font-size: var(--moduix-text-md);
    font-weight: var(--moduix-weight-regular);
    line-height: var(--moduix-line-height-text-md);
    letter-spacing: 0;
    overflow-wrap: anywhere;

    &[data-size='xs'] {
      font-size: var(--moduix-text-xs);
      line-height: var(--moduix-line-height-text-xs);
    }

    &[data-size='sm'] {
      font-size: var(--moduix-text-sm);
      line-height: var(--moduix-line-height-text-sm);
    }

    &[data-size='lg'] {
      font-size: var(--moduix-text-lg);
      line-height: var(--moduix-line-height-text-lg);
    }

    &[data-size='xl'] {
      font-size: var(--moduix-text-xl);
      line-height: var(--moduix-line-height-text-xl);
    }

    &[data-weight='medium'] {
      font-weight: var(--moduix-weight-medium);
    }

    &[data-weight='semibold'] {
      font-weight: var(--moduix-weight-semibold);
    }

    &[data-weight='bold'] {
      font-weight: var(--moduix-weight-bold);
    }

    &[data-tone='muted'] {
      color: var(--moduix-color-muted-foreground);
    }

    &[data-tone='primary'] {
      color: var(--moduix-color-primary);
    }

    &[data-tone='destructive'] {
      color: var(--moduix-color-destructive);
    }

    &[data-align='start'] {
      text-align: start;
    }

    &[data-align='center'] {
      text-align: center;
    }

    &[data-align='end'] {
      text-align: end;
    }

    &[data-align='left'] {
      text-align: left;
    }

    &[data-align='right'] {
      text-align: right;
    }

    &[data-align='justify'] {
      text-align: justify;
    }

    &[data-truncate] {
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }

    &[data-line-clamp] {
      display: -webkit-box;
      overflow: hidden;
      white-space: normal;
      -webkit-box-orient: vertical;
    }
  }
}
